-- Seed for Vedvis Herb
-- Generated by: node scripts/seed-products.mjs --sql
--
-- Paste into Supabase -> SQL Editor -> Run. Safe to run more than once:
-- rows that already exist (same name + sort_order) are skipped, not duplicated.
--
-- Every literal is cast to its column type (e.g. 350::numeric) so Postgres
-- does not infer text and fail the sort_order comparison.
-- Images are stored as filenames and resolve from /images at runtime, so this
-- file stays small.

insert into public.products (
  name, tagline, category, price, weight, description, long_description,
  how_to_use, benefits, ingredients, image, rating, reviews,
  sort_order, published
)
select
  v.name, v.tagline, v.category, v.price, v.weight, v.description,
  v.long_description, v.how_to_use, v.benefits, v.ingredients, v.image,
  v.rating, v.reviews, v.sort_order, v.published
from (values
    ('Kumkumadi Facial Gel'::text, 'Glow & Clear Skin'::text, 'Skincare'::text, 350::numeric, '50g'::text, 'Reduces acne, pimple. Reduces tanning and brings natural glow that stays longer on face.'::text, 'Reduces acne, pimple. Reduces tanning and brings natural glow that stays longer on face.'::text, 'Apply a small amount on clean face and neck after washing. Massage gently in circular motions. Use twice daily for best results.'::text, array['Reduces acne & pimples', 'Removes tanning', 'Brings natural glow', 'Long-lasting effect']::text[]::text[], array['KumkumadiTailam', 'Saffron', 'Sandalwood', 'Aloe Vera', 'Turmeric']::text[]::text[], 'IMG-20260713-WA0009.jpg'::text, 4.8::numeric, 0::integer, 0::integer, true::boolean),
    ('Kumkumadi Gel with 24K Gold'::text, 'Gold-Infused Glow'::text, 'Skincare'::text, 400::numeric, '50g | 25g - ₹200'::text, '24K gold particles make face glow. Removes tanning, acne, and pimple completely. Anti-aging formulation for youthful skin.'::text, 'Enriched with real 24K gold particles, this Kumkumadi gel gives your face a natural, luminous glow. It completely removes tanning, acne, and pimples while working as a powerful anti-aging formulation. Gold particles deeply penetrate the skin to stimulate collagen production, keeping your skin firm, youthful, and radiant.'::text, 'Apply a thin layer on clean face and neck after washing. Massage gently in upward circular motions until absorbed. Use twice daily for best results.'::text, array['Infused with 24K gold', 'Complete acne & pimple removal', 'Removes tanning', 'Anti-aging formulation', 'Natural face glow']::text[]::text[], array['24K Gold', 'KumkumadiTailam', 'Saffron', 'Sandalwood', 'Turmeric', 'Vitamin E']::text[]::text[], 'IMG-20260713-WA0010.jpg'::text, 4.9::numeric, 0::integer, 1::integer, true::boolean),
    ('Kumkumadi Facial Gel'::text, 'Herbal Skin Glow'::text, 'Skincare'::text, 299::numeric, '50g'::text, 'Handmade Ayurvedic facial gel with traditional Kumkumadi formulation. Brightens complexion and heals damaged skin naturally.'::text, 'Handmade Ayurvedic facial gel with traditional Kumkumadi formulation. Brightens complexion and heals damaged skin naturally.'::text, 'Take a pea-sized amount and apply on face. Massage gently in upward strokes. Use morning and night.'::text, array['Handmade formulation', 'Brightens complexion', 'Heals damaged skin', 'Suitable for all skin types']::text[]::text[], array['KumkumadiTailam', 'Manjistha', 'Saffron', 'Chandan', 'Glycerin']::text[]::text[], 'IMG-20260713-WA0011.jpg'::text, 4.7::numeric, 0::integer, 2::integer, true::boolean),
    ('Kumkumadi Miracle Beauty Oil'::text, 'Natural Glow Oil'::text, 'Oils'::text, 650::numeric, '10ml'::text, 'Provides natural glow on face. Reduces pimples and acne. Best for dry skin. Deeply nourishes and rejuvenates.'::text, 'Provides natural glow on face. Reduces pimples and acne. Best for dry skin. This luxurious Kumkumadi oil deeply nourishes and rejuvenates dry skin, bringing out a natural, healthy radiance. Regular use clears breakouts and keeps your skin soft, supple, and glowing.'::text, 'Take 2-3 drops on fingertips. Apply on clean face and massage gently in circular motions. Use at night for best results.'::text, array['Natural face glow', 'Reduces pimples & acne', 'Best for dry skin', 'Deep nourishment', 'Rejuvenates skin']::text[]::text[], array['Sesame Oil', 'Saffron', 'KumkumadiTailam', 'Lodhra', 'Manjistha', 'Vitamin E']::text[]::text[], 'IMG-20260713-WA0012.jpg'::text, 4.6::numeric, 0::integer, 3::integer, true::boolean),
    ('Kumkumadi Miracle Beauty Oil 24K Gold'::text, 'Gold Glow Therapy'::text, 'Oils'::text, 800::numeric, '10ml'::text, 'Retains natural glow on face. Completely removes pimple, acne. Reduces wrinkles, melasma, and pigmentation. Anti-aging gold therapy.'::text, 'Infused with real 24K gold, this Kumkumadi oil retains natural glow on face while completely removing pimples and acne. Reduces wrinkles, melasma, and pigmentation for youthful, radiant skin. Gold particles work deeply to repair and rejuvenate, giving you a flawless complexion.'::text, 'Warm 2-3 drops between palms. Press gently onto clean face and neck. Use nightly for best results.'::text, array['Retains natural glow', 'Removes pimple & acne', 'Reduces wrinkles', 'Reduces melasma & pigmentation', '24K gold therapy']::text[]::text[], array['24K Gold', 'Sesame Oil', 'KumkumadiTailam', 'Saffron', 'Lodhra', 'Chandan', 'Vitamin E']::text[]::text[], 'IMG-20260713-WA0013.jpg'::text, 4.8::numeric, 0::integer, 4::integer, true::boolean),
    ('Neem Tulsi Soap'::text, 'Anti-Acne Cleanser'::text, 'Skincare'::text, 149::numeric, '75g'::text, 'Combat acne and pimples naturally. Infused with Neem & Tulsi extracts to fight breakouts and give clear, radiant skin.'::text, 'Combat acne and pimples naturally. Infused with Neem & Tulsi extracts to fight breakouts and give clear, radiant skin.'::text, 'Lather between wet palms. Apply on face and body. Rinse thoroughly. Use daily.'::text, array['Fights acne & pimples', 'Purifies skin', 'Controls oil', 'Antibacterial']::text[]::text[], array['Neem Extract', 'Tulsi Extract', 'Glycerin', 'Coconut Oil', 'Natural Lye']::text[]::text[], 'IMG-20260713-WA0016.jpg'::text, 4.8::numeric, 0::integer, 5::integer, true::boolean),
    ('Herbal Hair Oil'::text, '3 Variants — 21, 36 & 51 Herbs'::text, 'Oils'::text, 329::numeric, '200ml'::text, 'Choose from 21 Herbs, 36 Herbs, or 51 Herbs Ayurvedic hair oil. Each variant is crafted through traditional Taila Pak Vidhi — slow-infusing herbs in coconut, sesame, and castor oil base for maximum potency.'::text, 'Handmade Ayurvedic hair oils prepared through the traditional Taila Pak Vidhi method — herbs are slowly infused in a base of coconut, sesame, and castor oils to preserve healing potency.

21 Herbs Hair Oil — formulated with Bhringraj, Amla, Brahmi, Hibiscus, Neem, Methi, Curry Leaves, Jatamansi, and more. Reduces hair loss, nourishes scalp, adds natural shine, and leaves hair soft and silky. Also effective against dandruff and scalp irritation.

36 Herbs Hair Oil — a richer blend including Sandalwood, Henna, Rose Petal, Manjistha, Kapoor Kachri, Nagarmotha, Liquorice, and 36 powerful herbs in total. Stops hair loss, stimulates new hair follicle growth, eliminates dandruff, improves blood circulation to the scalp, and prevents split ends and dryness.

51 Herbs Hair Oil — the most comprehensive formulation with all 36 herbs plus Moringa, Kalonji (Black Seed), Jojoba, Basil, Jasmine, Tea Tree, Rosemary, and Lavender. Addresses all hair problems — regrows hair follicles, removes dandruff, prevents premature greying and white hairs, reduces thinning, adds volume, and slows hair aging.'::text, 'Warm oil slightly. Apply on scalp and massage gently in circular motions for 5–10 minutes to improve blood circulation. Leave for 1–2 hours or overnight for deep nourishment. Wash with mild herbal shampoo. Use 2–3 times per week for best results.'::text, array['21 Herbs — reduces hair loss, natural shine, soft silky hair', '36 Herbs — stops hair loss, grows new follicles, anti-dandruff', '51 Herbs — all hair problems, prevents greying, adds volume', 'Taila Pak Vidhi — traditional slow-infusion method', 'No chemicals, parabens, or sulfates']::text[]::text[], array['21 Herbs: Bhringraj, Amla, Brahmi, Hibiscus, Neem, Methi, Curry Leaves, Jatamansi, Aloe Vera, Tulsi, Reetha, Shikakai, Kalonji, Coconut Oil, Sesame Oil, Castor Oil, Olive Oil, Jojoba Oil, Nagarmotha, Mulethi, Vitamin E', '36 Herbs: all 21 + Sandalwood, Henna, Rose Petal, Manjistha, Kapoor Kachri, Harad, Baheda, Orange Peel, Lemon Peel, Camphor, Karanj Oil, Indigo Leaf, Catechu, Coffee, Tea Leaf', '51 Herbs: all 36 + Moringa, Kalonji Oil, Basil, Jasmine, Tea Tree, Rosemary, Lavender, Grapeseed Oil, Almond Oil, Wheat Germ Oil, Flaxseed Oil, Sunflower Oil, Datura, Mandukaparni, Vach']::text[]::text[], 'IMG-20260713-WA0017.jpg'::text, 4.7::numeric, 0::integer, 6::integer, true::boolean),
    ('Moisturizer'::text, '4 Variants Available'::text, 'Skincare'::text, 150::numeric, '100ml'::text, 'Choose from Saffron, Lotus, Rose, or Jasmine moisturizer. Deeply hydrates, nourishes, and keeps skin soft and glowing all day.'::text, 'Available in 4 variants — Saffron Moisturizer for brightening, Lotus Moisturizer for soothing, Rose Moisturizer for hydration, and Jasmine Moisturizer for rejuvenation. Each variant provides deep moisture and lasting softness.'::text, 'Apply on clean face and neck after washing. Massage gently in upward strokes until absorbed. Use twice daily.'::text, array['Deep hydration', 'Nourishes skin', 'Soft & glowing skin', '4 variant options']::text[]::text[], array['Varies by variant — Saffron', 'Lotus', 'Rose', 'Jasmine', 'Aloe Vera', 'Vitamin E']::text[]::text[], 'IMG-20260713-WA0018.jpg'::text, 4.5::numeric, 0::integer, 7::integer, true::boolean),
    ('Face Wash'::text, '3 Variants Available'::text, 'Skincare'::text, 150::numeric, '50ml each'::text, 'Choose from Kumkumadi, Charcoal, or Neem Tulsi face wash. Each variant deeply cleanses, removes impurities, and keeps skin fresh and glowing.'::text, 'Available in 3 variants — Kumkumadi Face Wash for natural glow, Charcoal Face Wash for deep pore detox, and Neem Tulsi Face Wash for acne-free skin. Each variant gently cleanses and nourishes your skin.'::text, 'Take small amount on wet palm. Lather and massage on face in circular motions. Rinse thoroughly with water. Use twice daily.'::text, array['Deep cleansing', 'Removes impurities', 'Controls oil', 'Natural glow']::text[]::text[], array['Varies by variant — KumkumadiTailam', 'Activated Charcoal', 'Neem', 'Tulsi', 'Aloe Vera']::text[]::text[], 'IMG-20260713-WA0019.jpg'::text, 4.7::numeric, 0::integer, 8::integer, true::boolean),
    ('Kerala Herbal Shampoo'::text, 'Traditional Amla-Reetha-Shikakai Formula'::text, 'Haircare'::text, 249::numeric, '200ml'::text, 'A traditional Kerala-style herbal shampoo made with Amla, Reetha (soapnut), and Shikakai — the classic Ayurvedic trio that gently cleanses using natural saponins without stripping your scalp of natural oils.'::text, 'Inspired by the age-old Kerala tradition of washing hair with herbal powders, this handmade shampoo brings together Amla (Indian gooseberry), Reetha (soapnut), and Shikakai ("fruit for hair") — nature''s original cleansers. Shikakai gently cleanses and detangles while maintaining the scalp''s natural pH balance. Reetha provides natural saponins that create a mild lather to remove dirt and excess oil. Amla, the richest natural source of Vitamin C, strengthens hair follicles, nourishes roots, and helps prevent premature greying. Hibiscus flower deeply conditions and promotes hair growth. Neem and Aloe Vera soothe the scalp and fight dandruff, while Fenugreek and Brahmi strengthen hair from root to tip. Free from sulfates, parabens, and synthetic chemicals — just pure, handmade Kerala tradition in every wash.'::text, 'Wet hair thoroughly. Shake bottle well and apply an adequate amount to scalp and hair. Massage gently for 2–3 minutes, working into a mild lather. Leave on for 1–2 minutes for deeper nourishment. Rinse thoroughly with water. Follow with conditioner if needed. Suitable for daily use.'::text, array['Traditional Kerala Amla-Reetha-Shikakai formula', 'Gentle cleansing with natural saponins', 'Strengthens hair follicles & reduces fall', 'Prevents premature greying', 'Fights dandruff & soothes scalp', 'No sulfates, parabens, or chemicals']::text[]::text[], array['Amla (Indian Gooseberry)', 'Reetha (Soapnut)', 'Shikakai (Fruit for Hair)', 'Hibiscus Flower', 'Neem', 'Aloe Vera', 'Fenugreek (Methi)', 'Brahmi', 'Curry Leaves', 'Coconut Milk', 'Rose Water']::text[]::text[], 'IMG-20260713-WA0020.jpg'::text, 4.6::numeric, 0::integer, 9::integer, true::boolean),
    ('Kumkumadi Soap with 24K Gold'::text, 'Luxury Bath Bar'::text, 'Skincare'::text, 199::numeric, '100g'::text, 'Handmade Kumkumadi soap infused with 24K gold. Gently cleanses, moisturizes, and leaves skin soft, smooth, and glowing.'::text, 'Handmade Kumkumadi soap infused with 24K gold. Gently cleanses, moisturizes, and leaves skin soft, smooth, and glowing.'::text, 'Lather soap between wet palms or with a loofah. Apply on body. Rinse thoroughly.'::text, array['Infused with 24K gold', 'Moisturizing', 'Gentle cleansing', 'Natural glow']::text[]::text[], array['KumkumadiTailam', '24K Gold', 'Glycerin', 'Coconut Oil', 'Saffron']::text[]::text[], 'IMG-20260713-WA0021.jpg'::text, 4.8::numeric, 0::integer, 10::integer, true::boolean),
    ('Ubtan Soap'::text, '3-in-1 Ritual'::text, 'Skincare'::text, 169::numeric, '100g'::text, 'Traditional ubtan soap for deep moisturization, gentle exfoliation, and natural brightening all in one bar.'::text, 'Traditional ubtan soap for deep moisturization, gentle exfoliation, and natural brightening all in one bar.'::text, 'Lather with water. Apply on face and body. Massage gently to exfoliate. Rinse thoroughly.'::text, array['Deep moisturization', 'Gentle exfoliation', 'Natural brightening', 'Traditional ubtan recipe']::text[]::text[], array['Turmeric', 'Sandalwood', 'Gram Flour', 'Rose Water', 'Ghee']::text[]::text[], 'IMG-20260713-WA0023.jpg'::text, 4.7::numeric, 0::integer, 11::integer, true::boolean),
    ('Kumkumadi Toner Oil'::text, 'Saffron-Infused Glow Oil'::text, 'Oils'::text, 500::numeric, '10ml'::text, 'A classical Ayurvedic Kumkumadi Tailam made with Kashmiri saffron and 25+ botanicals in a cold-pressed sesame oil base. Brightens complexion, evens skin tone, and reduces dark spots naturally.'::text, 'Kumkumadi Tailam is a revered Ayurvedic formulation described in the classical texts of Bhavaprakasha and Ashtanga Hridayam. Made with Kashmiri saffron (Kumkuma), sandalwood, manjistha, liquorice, lotus, vetiver, and 20+ other herbs in a cold-pressed sesame oil base, it has been traditionally used as a daily facial oil to brighten complexion, even out skin tone, reduce dark spots and pigmentation, and restore natural radiance. Clinical studies show ~10% improvement in skin tone, ~13% reduction in redness, and improved firmness within 15 days of daily use without compromising skin barrier function.'::text, 'Cleanse face and pat dry. Take 2–3 drops onto palm, warm between hands, and gently massage onto face and neck using upward circular strokes for 2–3 minutes. Avoid eye area. Leave overnight and wash off in the morning with a mild cleanser. Use nightly for best results. For oily skin, use 2–3 drops, 3–4 nights a week. Always patch-test before first use.'::text, array['Brightens dull skin & evens tone', 'Reduces dark spots & pigmentation', 'Fades acne marks & blemishes', 'Anti-aging — reduces fine lines', 'Deeply nourishes without greasiness', 'Improves skin firmness & elasticity']::text[]::text[], array['Kashmiri Saffron (Kumkuma)', 'Sandalwood (Chandana)', 'Red Sandalwood (Rakta Chandana)', 'Manjistha (Indian Madder)', 'Liquorice (Yashtimadhu)', 'Lotus (Kamal)', 'Vetiver (Ushira)', 'Cold-Pressed Sesame Oil', 'Goat Milk', 'Rose Water']::text[]::text[], 'IMG-20260713-WA0024.jpg'::text, 4.5::numeric, 0::integer, 12::integer, true::boolean)
) as v (
  name, tagline, category, price, weight, description, long_description,
  how_to_use, benefits, ingredients, image, rating, reviews,
  sort_order, published
)
where not exists (
  select 1 from public.products p
  where p.name = v.name and p.sort_order = v.sort_order
);

